class TransientError(Exception):
    pass

job = {"id": "j1", "attempts": 1}
MAX_ATTEMPTS = 3
retry_queue = []
dead_letter_queue = []
try:
    raise TransientError()
except TransientError:
    if job["attempts"] < MAX_ATTEMPTS:
        retry_queue.append(job)
    else:
        dead_letter_queue.append(job)
